Record *make_record(Block *block, Record *parent, Utxo utxo, Integer *fees, const char *source) {
    Record *record = calloc(1, sizeof *record);
    record->block = block;
    record->parent = parent;
    record->utxo = utxo;
    record->transaction_fees = fees;
    record->source = copy_text(source);
    record->work = parent ? parent->work + ((Integer)1 << (4 * block->difficulty)) : 1;
    for (int i = 1; i < block->count; ++i)
        record->fees += fees[i - 1];
    return record;
}
Record *ancestor(Record *record, int height) {
    while (record->block->height > height)
        record = record->parent;
    return record;
}
Record **chain_to(Record *record, int *count) {
    *count = record->block->height + 1;
    Record **chain = malloc((size_t)*count * sizeof *chain);
    for (int i = *count - 1; i >= 0; --i) {
        chain[i] = record;
        record = record->parent;
    }
    return chain;
}
Record *fork_point(Record *a, Record *b) {
    int height = a->block->height < b->block->height ? a->block->height : b->block->height;
    a = ancestor(a, height);
    b = ancestor(b, height);
    while (a != b) {
        a = a->parent;
        b = b->parent;
    }
    return a;
}
char *header_text(Block *block) {
    return format("%d|%s|%s|%" PRId64 "|%d|%" PRId64, block->height, block->previous, block->root,
                  block->time, block->difficulty, block->nonce);
}
void hash_header(Block *block) {
    block->hash = digest(header_text(block));
}
Integer block_size(Block *block) {
    Integer size = 0;
    for (int i = 1; i < block->count; ++i)
        size += (Integer)strlen(block->transactions[i]->text);
    return size;
}
bool proof(Block *block) {
    for (int i = 0; i < block->difficulty; ++i)
        if (block->hash[i] != '0')
            return false;
    return true;
}
Block *parse_block(char **fields, char **texts, int count) {
    Block *block = calloc(1, sizeof *block);
    block->height = atoi(fields[3]);
    block->previous = fields[4];
    block->root = fields[5];
    block->time = strtoll(fields[6], NULL, 10);
    block->difficulty = atoi(fields[7]);
    block->nonce = strtoll(fields[8], NULL, 10);
    block->count = count;
    block->transactions = malloc((size_t)count * sizeof *block->transactions);
    for (int i = 0; i < count; ++i)
        block->transactions[i] = parse_transaction(texts[i]);
    hash_header(block);
    return block;
}
const char *context_error(Block *block, Integer limit) {
    if (!proof(block))
        return "bad-pow";
    char **ids = malloc((size_t)block->count * sizeof *ids);
    for (int i = 0; i < block->count; ++i)
        ids[i] = block->transactions[i]->id;
    char *root = merkle(ids, block->count);
    free(ids);
    if (strcmp(root, block->root))
        return "bad-merkle";
    if (block->transactions[0]->coinbase_height != block->height)
        return "bad-structure";
    for (int i = 1; i < block->count; ++i)
        if (block->transactions[i]->coinbase_height >= 0)
            return "bad-structure";
    return block_size(block) > limit ? "too-large" : NULL;
}
bool same_reference(Reference a, Reference b) {
    return a.index == b.index && !strcmp(a.id, b.id);
}
Coin *find_coin(Utxo *utxo, Reference reference) {
    for (int i = 0; i < utxo->count; ++i)
        if (same_reference(utxo->items[i].reference, reference))
            return utxo->items + i;
    return NULL;
}
bool mature(Coin coin, int height, int maturity) {
    return !coin.coinbase || coin.height == 0 || height >= coin.height + maturity;
}
Integer output_total(Transaction *tx) {
    Integer sum = 0;
    for (int i = 0; i < tx->output_count; ++i)
        sum += tx->outputs[i].amount;
    return sum;
}
const char *check_transaction(Transaction *tx, Utxo *utxo, Reference *spent, int spent_count, int height,
                              Wallets wallets, int maturity, Integer *fee) {
    *fee = 0;
    for (int i = 0; i < tx->output_count; ++i)
        if (!owner(wallets, tx->outputs[i].address) || tx->outputs[i].amount == 0)
            return "bad-output";
    Integer total = 0;
    for (int i = 0; i < tx->input_count; ++i) {
        Reference ref = tx->inputs[i];
        for (int j = 0; j < spent_count; ++j)
            if (same_reference(ref, spent[j]))
                return "double-spend";
        for (int j = 0; j < i; ++j)
            if (same_reference(ref, tx->inputs[j]))
                return "double-spend";
        Coin *coin = find_coin(utxo, ref);
        if (!coin)
            return "missing-input";
        if (!mature(*coin, height, maturity))
            return "immature";
        if (strcmp(tx->signatures[i], sign_transaction(owner(wallets, coin->address)->secret, i, tx->body)))
            return "bad-sig";
        total += coin->amount;
    }
    if (total < output_total(tx))
        return "overspend";
    *fee = total - output_total(tx);
    return NULL;
}
void apply_transaction(Utxo *utxo, Transaction *tx, int height) {
    for (int i = 0; i < tx->input_count; ++i) {
        Coin *coin = find_coin(utxo, tx->inputs[i]);
        if (coin) {
            int at = (int)(coin - utxo->items);
            memmove(coin, coin + 1, (size_t)(utxo->count - at - 1) * sizeof *coin);
            --utxo->count;
        }
    }
    for (int i = 0; i < tx->output_count; ++i) {
        Coin coin = {
            {tx->id, i}, tx->outputs[i].address, tx->outputs[i].amount, height, tx->coinbase_height >= 0};
        Coin *old = find_coin(utxo, coin.reference);
        if (old) {
            *old = coin;
            continue;
        }
        if (utxo->count == utxo->capacity) {
            utxo->capacity = utxo->capacity ? utxo->capacity * 2 : 16;
            utxo->items = realloc(utxo->items, (size_t)utxo->capacity * sizeof *utxo->items);
        }
        utxo->items[utxo->count++] = coin;
    }
}
Utxo copy_utxo(Utxo source) {
    Utxo result = {NULL, source.count, source.count};
    result.items = malloc((size_t)source.count * sizeof *result.items);
    memcpy(result.items, source.items, (size_t)source.count * sizeof *result.items);
    return result;
}
